    return parse_legacy_line(line)


def read_lines_from_file(filepath, is_gz=False):
    """Read lines from a file. For gz, handle truncation gracefully.
    Only return complete lines (ending in newline)."""
    if is_gz:
        with open(filepath, 'rb') as f:
            raw = f.read()
        try:
            with gzip.GzipFile(fileobj=__import__('io').BytesIO(raw)) as gz:
                data = gz.read()
        except Exception:
            # Truncated: use zlib to get what we can
            d = zlib.decompressobj(zlib.MAX_WBITS | 16)
            try:
                data = d.decompress(raw)
            except Exception:
                data = b''
            try:
                data += d.flush()
            except Exception:
                pass
        # Split and only keep complete lines (those that ended with \n)
        # The last segment after split may be incomplete
        parts = data.split(b'\n')
        # All parts except the last are complete lines
        # The last part is complete only if data ended with \n
        lines = []
        for i, part in enumerate(parts):
            if i < len(parts) - 1:
                # This line had a \n after it
                lines.append(part.decode('utf-8', errors='replace'))
            else:
                # Last part: only include if it's non-empty (meaning there was a \n before it)
                # Actually if data ends with \n, the last element is b'' which we skip
                # If data doesn't end with \n, this is an incomplete line
                if part:
                    # This is an incomplete line (no trailing newline) - skip it
                    pass
                # If part is b'', the file ended cleanly with \n, nothing to add
        return lines
    else:
        lines = []
        with open(filepath, 'r', errors='replace') as f:
            for line in f:
                # Each line from the iterator includes the \n
                lines.append(line.rstrip('\n'))
        return lines


def get_log_files(logdir):
    """Get valid log files from the directory."""
    valid_files = []
    for fname in os.listdir(logdir):
        # app.log
        if fname == 'app.log':
            valid_files.append((fname, False))
            continue
        # app.log.N
        m = re.match(r'^app\.log\.(\d+)$', fname)
        if m:
            valid_files.append((fname, False))
            continue
        # app.log.N.gz
        m = re.match(r'^app\.log\.(\d+)\.gz$', fname)
        if m:
            valid_files.append((fname, True))
            continue
        # Ignore everything else
    return valid_files


def main():
    if len(sys.argv) < 2:
        print("Usage: python3 p95.py LOGDIR")
        sys.exit(1)
    logdir = sys.argv[1]

    log_files = get_log_files(logdir)

    # Collect all records: request_id -> (ts, user, status, latency)
    # Keep only the latest timestamp per request_id
    best = {}  # request_id -> (ts, user, status, latency_ms)

    for fname, is_gz in log_files:
        filepath = os.path.join(logdir, fname)
        try:
            lines = read_lines_from_file(filepath, is_gz)
        except Exception:
            continue
        for line in lines:
            parsed = parse_line(line)
            if parsed is None:
                continue
            ts, user, req_id, status, latency = parsed
            if req_id not in best:
                best[req_id] = (ts, user, status, latency)
            else:
                # Keep the one with the latest timestamp
                old_ts = best[req_id][0]
                if ts > old_ts:
                    best[req_id] = (ts, user, status, latency)
                elif ts == old_ts:
                    # Tie: keep the one we see later (or could keep either)
                    best[req_id] = (ts, user, status, latency)

    # For each user, collect failed requests (status >= 500)
    user_failures = {}  # user -> list of latency_ms
    for req_id, (ts, user, status, latency) in best.items():
        if status >= 500:
            if user not in user_failures:
                user_failures[user] = []
            user_failures[user].append(latency)

    # Compute p95 for each user
    results = []
    for user, latencies in user_failures.items():
        n = len(latencies)
        latencies.sort()
        rank = math.ceil(0.95 * n)
        if rank < 1:
            rank = 1
        if rank > n:
            rank = n
        p95 = latencies[rank - 1]  # 1-based to 0-based
        results.append((user, n, p95))

    # Sort by failures descending, then user ascending
    results.sort(key=lambda x: (-x[1], x[0]))

    # Output
    print("user,failures,p95_ms")
    for user, failures, p95 in results:
        print(f"{user},{failures},{p95}")


if __name__ == '__main__':
    main()
